using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class NewchapelJunction : LayoutBase
{
    public NewchapelJunction()
    {
        Name = LayoutNamesEnums.NewchapelJunction;
        Owner = "S.Wilkins";
        Description = "Newchapel Junction is a finescale O Gauge layout representing the post-grouping period where the SR and the GWR ran together.</br></br>" +
            "The layout recreates the operation of a busy railway in its heyday with frequent arrivals and departures from the terminus station Newchapel Junction. The locomotives vary from express passenger and heavy freight engines to small tank engines of both SR and GWR origin.</br></br>" +
            "The main line train service consists of passenger and van trains which leave Newchapel Junction, complete a few laps of the circle and then return for their engines to be turned and run round for the next trip. Freight trains pull out of the yard at Newchapel Town, complete a few laps of the circle and return to the yard for re-marshalling, and near-continuous shunting in the large goods yard means each freight train has many wagons exchanged before it leaves.</br></br>" +
            "The branch line service consists of a variety of passenger and van trains leaving Newchapel Junction for the terminus at Sidport Regis via the single track branch, with a branch freight tripping between Newchapel Town yard and Sidport Regis. The layout is operated from five control panels and is entirely semaphore signalled. Moves between Newchapel Junction station and the circles are controlled by block instruments which also convey train descriptions by bell codes, as are moves between Newchapel Town and Sidport Regis, which use electro-mechanical block instruments. All signals and points are fully interlocked; those at Newchapel Junction are controlled by a relay operated push-button entrance-exit panel, while Sidport Regis has a mechanically interlocked lever frame.";
    }
}